class TestPrincipalMatching:
    """Test principal matching logic."""

    def test_principal_wildcard_and_exact_user(self):
        """Test wildcard and user principal matching."""
        # Wildcard matches anything
        request = {'subject': 'alice', 'roles': ['viewer'], 'action': 'a', 'resource': 'r'}
        policy = {'effect': 'ALLOW', 'principal': '*', 'action': 'a', 'resource': 'r'}
        assert impl.authorize(request, [policy]) == 'ALLOW'

        # user: matches exact subject
        request = {'subject': 'alice', 'roles': [], 'action': 'a', 'resource': 'r'}
        policy = {'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'a', 'resource': 'r'}
        assert impl.authorize(request, [policy]) == 'ALLOW'

        # user: does not match different subject
        request = {'subject': 'alice', 'roles': [], 'action': 'a', 'resource': 'r'}
        policy = {'effect': 'ALLOW', 'principal': 'user:bob', 'action': 'a', 'resource': 'r'}
        assert impl.authorize(request, [policy]) == 'DENY'

