class TestDenyOverrides:
    """Test deny-overrides combining algorithm."""

    def test_deny_overrides_allow_any_position(self):
        """Test that any matching DENY overrides matching ALLOW regardless of position."""
        request = {'subject': 'alice', 'roles': [], 'action': 'a', 'resource': 'r'}

